import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        long total = 0;
        HashMap<Long, Integer> freq = new HashMap<>();
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
            total += a[i];
            freq.merge(a[i], 1, Integer::sum);
        }
        long best = 0;
        for (long value : a) {
            long rest = total - value;
            if (rest % 2 != 0) continue;
            long half = rest / 2;
            if (freq.getOrDefault(half, 0) > (half == value ? 1 : 0)) best = Math.max(best, value);
        }
        System.out.println(best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	a := make([]int, n)
	total := 0
	freq := make(map[int]int, n)
	for i := range a {
		a[i] = nextInt()
		total += a[i]
		freq[a[i]]++
	}
	best := 0
	for _, value := range a {
		rest := total - value
		if rest%2 != 0 {
			continue
		}
		half := rest / 2
		need := 0
		if half == value {
			need = 1
		}
		if freq[half] > need {
			best = max(best, value)
		}
	}
	fmt.Println(best)
}
